let assert = require('assert');
let { z } = require('zod');

describe('zod .check', function () {
  it('validates an object with a custom cross‑field check', function () {
    const schema = z
      .object({
        password: z.string().min(8),
        confirmPassword: z.string(),
        anotherField: z.string(),
      })
      .check(
        z.refine((data) => data.password === data.confirmPassword, {
          message: 'Passwords do not match',
          path: ['confirmPassword'],
          // run the check only when there are no other issues on password/confirmPassword
          when(payload) {
            return payload.issues.every((iss) => {
              const firstPathEl = iss.path?.[0];
              return firstPathEl !== 'password' && firstPathEl !== 'confirmPassword';
            });
          },
        })
      );

    // ✅ valid data – should not throw
    assert.doesNotThrow(() => {
      schema.parse({
        password: 'abcdefgh',
        confirmPassword: 'abcdefgh',
        anotherField: 'foo',
      });
    });

    // ❌ mismatched passwords – should throw with our custom message
    try {
      schema.parse({
        password: 'abcdefgh',
        confirmPassword: 'abcd1234',
        anotherField: 'foo',
      });
      assert.fail('Expected validation error for mismatched passwords');
    } catch (e) {
      assert(
        e.errors.some((err) => err.message === 'Passwords do not match'),
        'Custom error message not found'
      );
    }
  });

  it('validates an array with a custom check function', function () {
    const UniqueStringArray = z.array(z.string()).check((ctx) => {
      // too many items
      if (ctx.value.length > 3) {
        ctx.issues.push({
          code: 'too_big',
          maximum: 3,
          origin: 'array',
          inclusive: true,
          message: 'Too many items 😡',
          input: ctx.value,
        });
      }
      // duplicate detection
      if (ctx.value.length !== new Set(ctx.value).size) {
        ctx.issues.push({
          code: 'custom',
          message: 'No duplicates allowed.',
          input: ctx.value,
        });
      }
    });

    // ✅ valid array
    assert.doesNotThrow(() => {
      UniqueStringArray.parse(['a', 'b', 'c']);
    });

    // ❌ array too large
    try {
      UniqueStringArray.parse(['a', 'b', 'c', 'd']);
      assert.fail('Expected too_big error');
    } catch (e) {
      assert(
        e.errors.some((err) => err.code === 'too_big'),
        'Did not receive "too_big" issue'
      );
    }

    // ❌ duplicate values
    try {
      UniqueStringArray.parse(['a', 'b', 'a']);
      assert.fail('Expected duplicate error');
    } catch (e) {
      assert(
        e.errors.some((err) => err.message === 'No duplicates allowed.'),
        'Did not receive duplicate‑value issue'
      );
    }
  });

  it('validates a string with a refined check', function () {
    const myString = z
      .string()
      .check(z.refine((val) => val.length > 8, { error: 'Too short!' }));

    // ✅ long enough string
    assert.doesNotThrow(() => {
      myString.parse('longenoughstring');
    });

    // ❌ short string – should emit our custom error
    try {
      myString.parse('short');
      assert.fail('Expected "Too short!" error');
    } catch (e) {
      assert(
        e.errors.some((err) => err.message === 'Too short!'),
        'Custom short‑string message not found'
      );
    }
  });
});
